lib='''"""Reusable grid functions for ARC-style tasks."""
from collections import Counter, deque

def background(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def outside_mask(grid, bg=None):
    """Boolean mask of background cells reachable from the border (4-connected)."""
    h, w = len(grid), len(grid[0])
    bg = background(grid) if bg is None else bg
    vis = [[False]*w for _ in range(h)]
    dq = deque()
    for i in range(h):
        for j in (0, w-1):
            if grid[i][j] == bg and not vis[i][j]:
                vis[i][j] = True; dq.append((i, j))
    for j in range(w):
        for i in (0, h-1):
            if grid[i][j] == bg and not vis[i][j]:
                vis[i][j] = True; dq.append((i, j))
    while dq:
        i, j = dq.popleft()
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            a, b = i+di, j+dj
            if 0 <= a < h and 0 <= b < w and grid[a][b] == bg and not vis[a][b]:
                vis[a][b] = True; dq.append((a, b))
    return vis

def enclosed_regions(grid, bg=None):
    """List of (cells, bbox) for each connected background region unreachable from the border."""
    h, w = len(grid), len(grid[0])
    bg = background(grid) if bg is None else bg
    vis = outside_mask(grid, bg)
    seen = [[False]*w for _ in range(h)]
    out = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == bg and not vis[i][j] and not seen[i][j]:
                cells, dq = [], deque([(i, j)])
                seen[i][j] = True
                while dq:
                    a, b = dq.popleft(); cells.append((a, b))
                    for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        x, y = a+di, b+dj
                        if 0 <= x < h and 0 <= y < w and grid[x][y] == bg and not vis[x][y] and not seen[x][y]:
                            seen[x][y] = True; dq.append((x, y))
                rs = [c[0] for c in cells]; cs = [c[1] for c in cells]
                out.append((cells, (min(rs), min(cs), max(rs), max(cs))))
    return out

def fill_rect_holes(grid, color=4, bg=None):
    """Fill each enclosed background pocket that sits inside a complete rectangular frame of non-background cells."""
    bg = background(grid) if bg is None else bg
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    for cells, (r0, c0, r1, c1) in enclosed_regions(g, bg):
        if r0 == 0 or c0 == 0 or r1 == h-1 or c1 == w-1:
            continue
        frame_ok = all(g[i][j] != bg for i in (r0-1, r1+1) for j in range(c0-1, c2 := c1+2)) \\
            if False else all(g[i][j] != bg for i in (r0-1, r1+1) for j in range(c0-1, c1+2)) \\
            and all(g[i][j] != bg for j in (c0-1, c1+1) for i in range(r0-1, r1+2))
        if frame_ok:
            for i, j in cells:
                g[i][j] = color
    return g
